struct string_buf {
    unsigned long long *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;
};

class stringx {
public:
    char *chars;
    string_buf *my_buf;
    stringx();
    stringx(const stringx &);
    ~stringx();
    void make_room(int);
    void append(const stringx &);
};

inline stringx operator+(const stringx &lhs, const stringx &rhs)
{
    stringx foo;
    foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
    foo.append(lhs);
    foo.append(rhs);
    return foo;
}

class os_file {
public:
    static bool file_exists(const stringx &filename);
};

