struct virtual_entry {
    short adjustment;
    short padding;
    void *function;
};

class entity {
    char fields_before_vtable[8];
    virtual_entry *vtable;

public:
    inline const stringx &get_dirname() const {
        const virtual_entry &entry = vtable[87];
        typedef const stringx &(*function_type)(const entity *);
        function_type function = (function_type)entry.function;
        return function((const entity *)((const char *)this + entry.adjustment));
    }
    inline bool has_dirname() const {
        const virtual_entry &entry = vtable[88];
        typedef bool (*function_type)(const entity *);
        function_type function = (function_type)entry.function;
        return function((const entity *)((const char *)this + entry.adjustment));
    }
    void load_anim(const stringx &filename) const;
};

void entity::load_anim( const stringx& filename ) const
{
  if ( has_dirname() )
  {
    stringx local = get_dirname() + filename;
    if ( os_file::file_exists( local ) )
    {
      g_world_ptr->get_ett_manager()->load( local );
      return;
    }
  }
  g_world_ptr->get_ett_manager()->load( filename );
}
